INSERT INTO learnings VALUES('c-czxl','p-0oin','t-inspect-contracts','default','decision','chief-core can only use existing chief_event_log_proto::schema::Event variants because task scope forbids editing prototypes/event-log. OAuth milestone signed events will be appended as Event::UIAction { surface: "oauth", action: "OAuthFlowStarted|OAuthFlowCompleted|OAuthProxyRequest", payload_hash } so they are signed by EventLog while preserving the requested milestone names.','2026-04-22 02:12:49');
INSERT INTO learnings VALUES('c-qeff','p-0oin','t-inspect-contracts','default','discovery','chief-oauth API: OAuthBroker::new(path), start_flow(Provider, &[String], redirect_uri) -> AuthorizationChallenge, complete_flow(FlowId, code, state) -> SessionHandle, proxy_request(&SessionHandle, ProxyRequest) -> ProxyResponse. Provider has google/github/custom; SessionHandle serializes without tokens; ProxyResponse needs a chief-core JSON wrapper.','2026-04-22 02:12:49');
INSERT INTO learnings VALUES('c-pjqv','p-0oin','t-state-capability','default','discovery','Implemented state/capability wiring: AppState owns Arc<chief_oauth::OAuthBroker> initialized at state_dir/oauth; RequestedOp::NetOauth2(provider, scopes) and factory added; CapabilityKind::NetOauth2 now enforces exact provider match except wildcard dev grant and grant scope superset.','2026-04-22 02:16:21');
INSERT INTO learnings VALUES('c-ttzn','p-0oin','t-broker-check','default','discovery','Broker enforcement now explicitly evaluates CapabilityKind::NetOauth2 in broker.rs. Providers are exact string matches with ''*'' only for wildcard/dev grants; requested scopes must all be present unless grant scopes contain ''*''.','2026-04-22 02:16:53');
INSERT INTO learnings VALUES('c-u3gu','p-0oin','t-routes','default','discovery','Added /oauth/start, /oauth/complete, /oauth/proxy handlers. Start/proxy check RequestedOp::net_oauth2; complete returns SessionHandle directly. OAuth milestones append signed Event::UIAction entries with actions OAuthFlowStarted, OAuthFlowCompleted, OAuthProxyRequest because event-log schema cannot be edited in this scoped task.','2026-04-22 02:19:00');
